<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { consultarAnalisisCuentas, obtenerMesesAnalisis, obtenerOpcionesAnalisis } from '../services/analisisCuentas'
import type { AnalisisCuentasFiltros, CuentaAnalisis, CuentaAnalisisOption, MesAnalisis } from '../interfaces/analisisCuentas.interface'
const filtros=reactive<AnalisisCuentasFiltros>({cuenta_desde:'',cuenta_hasta:'',anio:null,mes_inicio:null,mes_fin:null}),anios=ref<number[]>([]),cuentas=ref<CuentaAnalisisOption[]>([]),meses=ref<MesAnalisis[]>([]),resultados=ref<CuentaAnalisis[]>([]),loading=ref(false),consultado=ref(false),error=ref('')
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la consulta.'
const money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
async function load(){loading.value=true;try{const r=await obtenerOpcionesAnalisis();anios.value=r.anios;cuentas.value=r.cuentas;meses.value=r.meses??[];resultados.value=r.data?.cuentas??[]}catch(v){error.value=message(v)}finally{loading.value=false}}
async function changeYear(){filtros.mes_inicio=null;filtros.mes_fin=null;meses.value=filtros.anio?await obtenerMesesAnalisis(filtros.anio):[]}
async function search(){if(!filtros.cuenta_desde||!filtros.cuenta_hasta||!filtros.anio||!filtros.mes_inicio||!filtros.mes_fin)return void(error.value='Complete todos los filtros.');if(filtros.cuenta_desde>filtros.cuenta_hasta)return void(error.value='La cuenta inicial no puede ser mayor que la cuenta final.');if(filtros.mes_inicio>filtros.mes_fin)return void(error.value='El mes inicial no puede ser mayor que el mes final.');loading.value=true;error.value='';consultado.value=true;try{const r=await consultarAnalisisCuentas(filtros);resultados.value=r.data?.cuentas??[]}catch(v){error.value=message(v)}finally{loading.value=false}}
function clear(){Object.assign(filtros,{cuenta_desde:'',cuenta_hasta:'',anio:null,mes_inicio:null,mes_fin:null});meses.value=[];resultados.value=[];consultado.value=false;error.value=''}
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/proceso-contable">Proceso contable</RouterLink> / Análisis de cuentas</nav><header class="hero"><div class="mark">AC</div><div><small>MIA · CONTABILIDAD · PROCESO</small><h1>Análisis de cuentas</h1><p>Consulta movimientos, saldos anteriores y balances por cuenta y periodo.</p></div></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="search"><label>Cuenta inicial *<select v-model="filtros.cuenta_desde"><option value="">Seleccione</option><option v-for="c in cuentas" :key="c.cta_contable" :value="c.cta_contable">{{c.cta_contable}} - {{c.descripcion}}</option></select></label><label>Cuenta final *<select v-model="filtros.cuenta_hasta"><option value="">Seleccione</option><option v-for="c in cuentas" :key="c.cta_contable" :value="c.cta_contable">{{c.cta_contable}} - {{c.descripcion}}</option></select></label><label>Año *<select v-model="filtros.anio" @change="changeYear"><option :value="null">Seleccione</option><option v-for="a in anios" :key="a" :value="a">{{a}}</option></select></label><label>Mes inicial *<select v-model="filtros.mes_inicio"><option :value="null">Seleccione</option><option v-for="m in meses" :key="m.mes" :value="m.mes">{{m.mes_label}}</option></select></label><label>Mes final *<select v-model="filtros.mes_fin"><option :value="null">Seleccione</option><option v-for="m in meses" :key="m.mes" :value="m.mes">{{m.mes_label}}</option></select></label><footer><button type="button" class="soft" @click="clear">Limpiar</button><button :disabled="loading">{{loading?'Consultando…':'Consultar'}}</button></footer></form><div v-if="loading" class="empty">Procesando análisis contable…</div><div v-else-if="consultado&&!resultados.length" class="empty">No se encontraron movimientos para los filtros seleccionados.</div><div v-else-if="!consultado" class="empty">Seleccione las cuentas y el periodo que desea analizar.</div><section v-for="cuenta in resultados" :key="cuenta.cta_contable" class="account"><header><b>{{cuenta.cta_contable}} - {{cuenta.denominacion}}</b><span>{{cuenta.movimientos.length}} movimientos</span></header><div v-if="cuenta.movimientos.length" class="scroll"><table><thead><tr><th>N.°</th><th>Fecha</th><th>Glosa</th><th>Referencia</th><th>Código</th><th>Denominación</th><th>Debe S/</th><th>Haber S/</th></tr></thead><tbody><tr v-for="mov in cuenta.movimientos" :key="`${cuenta.cta_contable}-${mov.nro}`"><td>{{mov.nro}}</td><td>{{mov.fecha}}</td><td>{{mov.glosa}}</td><td>{{mov.ref_operacion||'—'}}</td><td><b>{{mov.cta_contable}}</b></td><td>{{mov.denominacion}}</td><td class="num">{{money(mov.debe)}}</td><td class="num">{{money(mov.haber)}}</td></tr></tbody></table></div><p v-else class="notice">Sin movimientos en el periodo.</p><table class="totals"><tbody><tr><th>Total cuenta</th><td>{{money(cuenta.total_debe)}}</td><td>{{money(cuenta.total_haber)}}</td></tr><tr class="previous"><th>Saldo anterior</th><td>{{money(cuenta.saldo_ant_debe)}}</td><td>{{money(cuenta.saldo_ant_haber)}}</td></tr><tr><th>Diferencia anterior</th><td colspan="2">{{money(cuenta.saldo_ant_diff)}}</td></tr><tr class="balance"><th>Total balance</th><td>{{money(cuenta.total_balance_debe)}}</td><td>{{money(cuenta.total_balance_haber)}}</td></tr><tr><th>Diferencia balance</th><td colspan="2">{{money(cuenta.total_balance_diff)}}</td></tr></tbody></table></section></div></template>
<style scoped>
